arguments.command:
cat /app/resources/treasury_bulletin_2012_06.json | python3 -c "
import json, sys
d = json.load(sys.stdin)
pages = d['document']['pages']
# Look for tables with employment and general retirement
for i, page in enumerate(pages):
    if 'tables' in page:
        for table in page.get('tables', []):
            for row in table.get('rows', []):
                row_str = str(row)
                if 'Employment and general retirement' in row_str and 'Net' in row_str:
                    print(f'Page {i+1}:', row)
" | head -30
